import React from "react";

// Imagem embutida em Base64 para garantir carregamento instantâneo e sem falhas em impressão, offline e em qualquer ambiente
export const POLICIA_PENAL_LOGO_SRC = "data:image/png;base64,";

interface PoliciaPenalLogoProps {
  className?: string;
  alt?: string;
}

export const PoliciaPenalLogo: React.FC<PoliciaPenalLogoProps> = ({ 
  className = "h-16 w-auto object-contain",
  alt = "Brasão Polícia Penal SP" 
}) => {
  return (
    <img 
      src={POLICIA_PENAL_LOGO_SRC} 
      alt={alt}
      className={className}
      loading="eager"
      decoding="sync"
    />
  );
};

export default PoliciaPenalLogo;
